WITH flattened AS (SELECT id, plan, currency, EXPLODE(tier_limits) AS val FROM price_tiers) SELECT *, RANK() OVER (PARTITION BY currency ORDER BY val) AS val_rank, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY val DESC NULLS LAST) AS val_percent_rank, AVG(val) OVER (PARTITION BY currency) AS currency_avg_val, PERCENT_RANK() OVER (ORDER BY val DESC NULLS LAST) AS val_percent_rank_2, RANK() OVER (PARTITION BY plan ORDER BY val) AS val_rank_2 FROM flattened;
